"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";

/* ===================== Types ===================== */

type TreasuryAccount = {
  id: number;
  title: string;
  type: "BANK" | "CASH" | "PETTY_CASH";
};

type PurchaseItem = {
  productId: number;
  productName?: string;
  qty: string;
  unitPrice: string;
  note?: string;
};

type PaymentMethod = "CASH" | "CARD" | "TRANSFER";

/* ===================== Helpers ===================== */

function keepDigitsOnly(v: string) {
  return (v || "").replace(/[^\d]/g, "");
}

function formatThousandsFa(v: string | number | null | undefined) {
  if (v == null) return "";
  const s = String(v).replace(/[^\d]/g, "");
  return s.replace(/\B(?=(\d{3})+(?!\d))/g, "٬");
}

/* ===================== Component ===================== */

export default function PurchaseFormClient() {
  const router = useRouter();

  /* -------- basic states -------- */
  const [warehouseId, setWarehouseId] = useState<number | null>(null);
  const [partyId, setPartyId] = useState<number | null>(null);
  const [description, setDescription] = useState("");

  /* -------- items -------- */
  const [items, setItems] = useState<PurchaseItem[]>([]);

  /* -------- payment -------- */
  const [paymentMethod, setPaymentMethod] = useState<PaymentMethod>("CASH");
  const [paidAmountDigits, setPaidAmountDigits] = useState("");
  const paidAmount = Number(paidAmountDigits || 0);

  const [treasuryAccounts, setTreasuryAccounts] = useState<TreasuryAccount[]>([]);
  const [paymentAccountId, setPaymentAccountId] = useState<number | null>(null);

  /* -------- ui -------- */
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  /* ===================== Load Treasury Accounts ===================== */

  useEffect(() => {
    (async () => {
      try {
        const res = await fetch("/api/treasury/accounts", { cache: "no-store" });
        const data = await res.json();
        setTreasuryAccounts(Array.isArray(data) ? data : []);
      } catch (e) {
        console.error("load treasury accounts error", e);
      }
    })();
  }, []);

  /* ===================== Submit ===================== */

  async function handleSubmit() {
    setError(null);

    if (!warehouseId) {
      setError("انتخاب انبار الزامی است");
      return;
    }
    if (!items.length) {
      setError("حداقل یک قلم خرید وارد کنید");
      return;
    }

    if (paidAmount > 0 && !paymentAccountId) {
      setError("برای پرداخت، انتخاب حساب خزانه الزامی است");
      return;
    }

    setLoading(true);
    try {
      const res = await fetch("/api/inventory/purchases", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          warehouseId,
          partyId,
          description,

          items: items.map((it) => ({
            productId: it.productId,
            qty: it.qty,
            unitPrice: it.unitPrice,
            note: it.note,
          })),

          payment: {
            method: paymentMethod,
            amount: paidAmount > 0 ? paidAmount : undefined,
            fromAccountId: paidAmount > 0 ? paymentAccountId : null,
          },
        }),
      });

      const data = await res.json();
      if (!res.ok) throw new Error(data?.message || "خطا در ثبت خرید");

      router.push("/dashboard/inventory/purchases");
    } catch (e: any) {
      setError(e.message);
    } finally {
      setLoading(false);
    }
  }

  /* ===================== UI ===================== */

  return (
    <div className="space-y-6">

      {error && (
        <div className="rounded-xl bg-red-50 p-3 text-sm text-red-700">
          {error}
        </div>
      )}

      {/* ===================== Payment Section ===================== */}
      <div className="rounded-xl border p-4 space-y-3">
        <h3 className="font-bold">پرداخت فاکتور خرید</h3>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-3">

          {/* method */}
          <div>
            <label className="text-xs text-zinc-500">روش پرداخت</label>
            <select
              className="input"
              value={paymentMethod}
              onChange={(e) => setPaymentMethod(e.target.value as PaymentMethod)}
            >
              <option value="CASH">نقدی</option>
              <option value="CARD">کارت به کارت</option>
              <option value="TRANSFER">انتقال بانکی</option>
            </select>
          </div>

          {/* amount */}
          <div>
            <label className="text-xs text-zinc-500">مبلغ پرداختی</label>
            <input
              dir="ltr"
              inputMode="numeric"
              className="input"
              value={formatThousandsFa(paidAmountDigits)}
              onChange={(e) =>
                setPaidAmountDigits(keepDigitsOnly(e.target.value))
              }
            />
          </div>

          {/* treasury account */}
          <div>
            <label className="text-xs text-zinc-500">حساب پرداختی</label>
            <select
              className="input"
              value={paymentAccountId ?? ""}
              onChange={(e) =>
                setPaymentAccountId(
                  e.target.value ? Number(e.target.value) : null
                )
              }
            >
              <option value="">انتخاب حساب خزانه</option>
              {treasuryAccounts.map((a) => (
                <option key={a.id} value={a.id}>
                  {a.title} ({a.type === "BANK" ? "بانک" : "صندوق"})
                </option>
              ))}
            </select>
          </div>
        </div>
      </div>

      {/* ===================== Actions ===================== */}
      <div className="flex gap-3">
        <button
          disabled={loading}
          onClick={handleSubmit}
          className="rounded-xl bg-emerald-600 px-6 py-2 text-white hover:bg-emerald-700 disabled:opacity-60"
        >
          ثبت خرید
        </button>

        <button
          type="button"
          onClick={() => router.back()}
          className="rounded-xl border px-6 py-2"
        >
          انصراف
        </button>
      </div>
    </div>
  );
}
